payload.css:
:host { display: block; color: #fff; font: 600 14px ui-sans-serif, system-ui, sans-serif; user-select: none; }
.hud { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
[data-ui-slot="score"] { position: absolute; top: 12px; left: 14px; padding: 4px 10px; background: rgb(0 0 0 / 45%); border-radius: 8px; }
[data-ui-slot="target-status"] { position: absolute; top: 48px; left: 14px; max-width: 250px; padding: 6px 10px; background: rgb(10 18 34 / 84%); border: 1px solid rgb(255 236 128 / 58%); border-radius: 8px; color: #ffec80; font-size: 12px; letter-spacing: .025em; }
[data-ui-slot="target-status"][data-state="damaged"] { color: #fff4b0; border-color: rgb(255 150 90 / 75%); }
[data-ui-slot="target-status"][data-state="disabled"] { color: #b9ffcf; border-color: rgb(123 255 167 / 70%); }
[data-ui-slot="charge"] { position: absolute; top: 86px; left: 14px; width: 230px; box-sizing: border-box; padding: 7px 10px; background: rgb(10 18 34 / 84%); border: 1px solid rgb(98 214 255 / 52%); border-radius: 8px; color: #bdefff; font-size: 12px; letter-spacing: .02em; }
[data-ui-slot="charge"][data-state="charging"] { border-color: rgb(98 214 255 / 92%); box-shadow: 0 0 14px rgb(51 194 255 / 28%); color: #e6fbff; }
[data-ui-slot="charge"][data-state="released"] { border-color: rgb(255 236 128 / 85%); color: #ffec80; }
[data-ui-slot="charge-label"] { display: block; min-height: 1.35em; }
[data-ui-slot="charge-meter"] { display: block; height: 5px; margin-top: 6px; overflow: hidden; background: rgb(255 255 255 / 14%); border-radius: 999px; }
[data-ui-slot="charge-fill"] { display: block; width: 0%; height: 100%; background: linear-gradient(90deg, #54dfff, #c6f7ff); border-radius: inherit; transition: width 80ms linear; }
[data-ui-slot="charge"][data-state="released"] [data-ui-slot="charge-fill"] { background: linear-gradient(90deg, #ffcf5a, #fff2ac); }
[data-ui-slot="combo"] { position: absolute; top: 146px; left: 14px; width: 230px; box-sizing: border-box; padding: 6px 10px; background: rgb(10 18 34 / 84%); border: 1px solid rgb(123 255 167 / 55%); border-radius: 8px; color: #b9ffcf; font-size: 12px; letter-spacing: .02em; }
[data-ui-slot="combo"][data-state="active"] { border-color: rgb(255 236 128 / 82%); color: #ffec80; box-shadow: 0 0 12px rgb(255 236 128 / 18%); }
[data-ui-slot="combo"][data-state="expired"] { border-color: rgb(255 150 90 / 64%); color: #ffc18d; }
[data-ui-slot="mission"] { position: absolute; top: 12px; left: 50%; transform: translateX(-50%); padding: 7px 14px; background: rgb(10 18 34 / 82%); border: 1px solid rgb(255 236 128 / 55%); border-radius: 9px; color: #ffec80; letter-spacing: .01em; }
[data-ui-slot="mission"][data-complete="true"] { color: #b9ffcf; border-color: rgb(123 255 167 / 65%); }
button { position: absolute; top: 12px; right: 14px; pointer-events: auto; padding: 6px 12px; color: #fff; background: rgb(20 28 48 / 78%); border: 1px solid rgb(255 255 255 / 25%); border-radius: 8px; font: inherit; }
button:disabled { cursor: not-allowed; opacity: .48; }
.settings-action { right: 150px; }
.asset-lab { position: absolute; right: 14px; bottom: 12px; width: 304px; box-sizing: border-box; pointer-events: auto; padding: 8px 10px; color: #dbe7ff; background: rgb(10 18 34 / 88%); border: 1px solid rgb(255 255 255 / 20%); border-radius: 8px; font-weight: 500; }
.asset-lab summary { cursor: pointer; font-weight: 700; }
.asset-lab-copy { margin: 8px 0; color: #b8c6e4; font-size: 12px; line-height: 1.35; }
.asset-controls { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; }
.asset-control { position: static; top: auto; right: auto; width: 100%; padding: 5px 6px; color: #dbe7ff; background: rgb(255 255 255 / 8%); border-color: rgb(255 255 255 / 22%); font-size: 12px; text-align: left; }
.asset-control:hover, .asset-control:focus-visible { background: rgb(255 236 128 / 18%); border-color: rgb(255 236 128 / 58%); }
[data-ui-slot="asset-lab-status"] { display: block; min-height: 1.35em; margin-top: 8px; color: #b8c6e4; font-size: 12px; }
[data-ui-slot="asset-lab-status"][data-state="active"] { color: #ffec80; }
[data-ui-slot="asset-lab-status"][data-state="restored"] { color: #b9ffcf; }
[data-ui-slot="asset-lab-status"][data-state="unavailable"] { color: #ff9b9b; }
kbd { min-width: 1.2em; display: inline-block; padding: 1px 4px; text-align: center; color: #ffec80; background: rgb(255 255 255 / 10%); border-radius: 4px; }
[data-ui-slot="crosshair"] { position: absolute; inset: 50% auto auto 50%; display: none; font-size: 24px; transform: translate(-50%, -50%); }
[data-ui-slot="hint"] { position: absolute; bottom: 14px; left: 50%; transform: translateX(-50%); padding: 4px 9px; background: rgb(0 0 0 / 38%); border-radius: 7px; }
[data-ui-slot="lock-status"] { position: absolute; top: 88px; left: 14px; }
.score-popup { color: #ffec80; font-size: 22px; }
